const inItems = $input.all().map(i => i.json);

// Support BOTH shapes:
// 1) One item with payload.items = [accounts...]
// 2) Multiple items where each item IS an account
let accounts = [];
for (const it of inItems) {
  if (it && Array.isArray(it.items)) accounts.push(...it.items);
  else if (it) accounts.push(it);
}

const out = [];

for (const acc of accounts) {
  const account_key = acc.account_key || 'unknown';
  const uid = acc.uid || '';
  const fetched_at = acc.fetched_at || acc.generated_at || new Date().toISOString();

  const posts = Array.isArray(acc.posts) ? acc.posts : [];
  for (const p of posts) {
    const post_id = (p.post_id || '').toString();
    const created_at = p.created_at || fetched_at;
    const permalink = p.permalink || p.scheme_url || '';
    const text_cn = ((p.text_cn || p.text || '') + '').trim();

    if (!text_cn) continue;

    const fingerprint = post_id
      ? account_key + '|' + post_id
      : account_key + '|' + created_at + '|' + permalink;

    out.push({
      json: {
        account_key,
        uid,
        fetched_at,
        post_id,
        created_at,
        permalink,
        text_cn,
        fingerprint,
        raw_json: JSON.stringify(p.raw || p)
      }
    });
  }
}

return out;

function normalizeWeiboText(s) {
  s = (s || '').toString();
  s = s.replace(/\r\n/g, '\n');
  s = s.replace(/[ \t]+/g, ' ');
  s = s.replace(/\n{3,}/g, '\n\n');
  return s.trim();
}

function escapeNewlinesForStorage(s) {
  // For Sheets storage: convert real newlines into literal \\n
  return (s || '').toString()
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\n/g, '\\n');
}

const base = ($json && typeof $json === 'object' && !Array.isArray($json))
  ? $json
  : { text_cn: String($json ?? '') };

const cleaned_cn_raw = normalizeWeiboText(base.text_cn);
const cleaned_cn_escaped = escapeNewlinesForStorage(cleaned_cn_raw);

return {
  ...base,
  cleaned_cn_raw,
  cleaned_cn_escaped
};

