const j = $json;

// Telegram multiline WITHOUT real \n: use U+2028
const LS = '\u2028';

// MarkdownV2 escape (official special chars)
function escMdV2(s) {
  s = (s ?? '').toString();
  return s.replace(/([_\*\[\]\(\)~`>#+\-=|{}\.!\\])/g, '\\$1');
}

function toTelegramLines(s) {
  return (s ?? '').toString()
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .split('\n')
    .join(LS);
}

function clip(s, maxLen) {
  s = (s ?? '').toString();
  if (s.length <= maxLen) return s;
  return s.slice(0, Math.max(0, maxLen - 1)) + '…';
}

const ACCOUNT_STYLE = {
  f2lam: { title: 'F2 Lam', emoji: '🟣' },
  f2ma: { title: 'F2 Ma', emoji: '🔵' }
};

const style = ACCOUNT_STYLE[j.account_key] || { title: j.account_key || 'unknown', emoji: '🧵' };

const cn = clip(j.cleaned_cn_raw || j.text_cn || '', 1800);
const vi = clip(j.vi_final_raw || j.translation_vi_raw || '', 1800);

const header = '*' + escMdV2(style.emoji) + '\u00A0' + escMdV2(style.title) + '*';
const cnBlock = '*🇨🇳\u00A0Original\u00A0CN:*' + LS + escMdV2(toTelegramLines(cn));
const viBlock = '*🇻🇳\u00A0Vietnamese:*' + LS + escMdV2(toTelegramLines(vi));
const linkLine = '*🔗\u00A0Link:*' + LS + escMdV2(toTelegramLines(j.permalink || ''));

const msg = [header, cnBlock, viBlock, linkLine].join(LS + LS);

return { ...j, telegram_message: msg };

const j = $json;

const LS = "\u2028";

function escMdV2(s) {
  s = (s ?? "").toString();
  // MarkdownV2 special chars: _ * [ ] ( ) ~ ` > # + - = | { } . ! and backslash
  return s.replace(/([_\*\$begin:math:display$\$end:math:display$\$begin:math:text$\$end:math:text$~`>#+\-=|{}\.!\\])/g, "\\$1");
}

function toTelegramLines(s) {
  return (s ?? "").toString()
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .split("\n")
    .join(LS);
}

function clip(s, maxLen) {
  s = (s ?? "").toString();
  if (s.length <= maxLen) return s;
  return s.slice(0, Math.max(0, maxLen - 1)) + "…";
}

const ACCOUNT_STYLE = {
  f2lam: { title: "F2 Lam", emoji: "🟣" },
  f2ma: { title: "F2 Ma", emoji: "🔵" }
};

const style = ACCOUNT_STYLE[j.account_key] || { title: j.account_key || "unknown", emoji: "🧵" };

const cn = clip(j.cleaned_cn_raw || j.text_cn || "", 2600);

const header = "*" + escMdV2(style.emoji) + "\u00A0" + escMdV2(style.title) + "*";
