const linkLine = "*🔗\u00A0Link:*" + LS + escMdV2(toTelegramLines(j.permalink || ""));

const msg = [header, cnBlock, linkLine].join(LS + LS);

return { ...j, telegram_message: msg };

const FORUM_CHAT_ID = Number($env.TG_FORUM_CHAT_ID);

const THREAD_MAP = {
  f2lam: 2,
  f2ma: 3
};

const thread_id = THREAD_MAP[$json.account_key] || null;

return { ...$json, forum_chat_id: FORUM_CHAT_ID, thread_id };

const j = $json;

const MAX = 3900; // keep margin under 4096
const LS = '\u2028';

const text = (j.telegram_message || '').toString();
const blocks = text.split(LS + LS);

const parts = [];
let cur = '';

function pushCur() {
  if (cur) parts.push(cur);
  cur = '';
}

for (const b of blocks) {
  const block = b || '';
  const candidate = cur ? (cur + LS + LS + block) : block;

  if (candidate.length <= MAX) {
    cur = candidate;
    continue;
  }

  if (cur) pushCur();

  if (block.length > MAX) {
    const lines = block.split(LS);
    let cur2 = '';
    for (const line of lines) {
      const cand2 = cur2 ? (cur2 + LS + line) : line;
      if (cand2.length <= MAX) {
        cur2 = cand2;
      } else {
        if (cur2) parts.push(cur2);
        let rest = line;
        while (rest.length > MAX) {
          parts.push(rest.slice(0, MAX));
          rest = rest.slice(MAX);
        }
        cur2 = rest;
      }
    }
    if (cur2) parts.push(cur2);
  } else {
    cur = block;
  }
}

if (cur) pushCur();

// MarkdownV2 escape for notice line (only escape backticks by removing them)
const safeKey = (j.account_key || 'unknown').toString().replace(/`/g, '');
const notice = '*No\u00A0topic\u00A0mapping\u00A0for:*' + LS + '`' + safeKey + '`' + LS + LS;

return parts.map((p, idx) => ({
  json: {
    ...j,
    telegram_part: p,
    telegram_part_fallback: (idx === 0) ? (notice + p) : p,
    part_index: idx,
    part_count: parts.length
  }
}));
